evidence.en:
// app, behind PgBouncer pool_mode = transaction
await db.query('SELECT pg_advisory_lock($1)', [key]);
// ... several separate queries (each may run on a DIFFERENT pooled backend) ...
await db.query('SELECT pg_advisory_unlock($1)', [key]);
// symptom: lock sometimes held on a connection a later request reuses; never cleanly released

evidence.ru:
// приложение за PgBouncer pool_mode = transaction
await db.query('SELECT pg_advisory_lock($1)', [key]);
// ... несколько отдельных запросов (каждый может идти на ДРУГОЙ пулинговый backend) ...
await db.query('SELECT pg_advisory_unlock($1)', [key]);
// симптом: блокировка иногда висит на соединении, переиспользуемом поздним запросом; чисто не освобождается
